function validate([stones]) {
  if (!Array.isArray(stones) || stones.length < 2 || stones.length > 1000) return 'stones needs 2 to 1000 values.';
  if (stones.some(v => !Number.isInteger(v) || v < 1 || v > 1000)) return 'Each stone is a whole number from 1 to 1000.';
  return null;
}

