function stoneGameVII(stones) {
  const n = stones.length;
  const prefix = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) {
    prefix[i + 1] = prefix[i] + stones[i];
  }
  const dp = Array.from({ length: n }, () => new Array(n).fill(0));
  for (let left = n - 2; left >= 0; left--) {
    for (let right = left + 1; right < n; right++) {
      const takeLeft = prefix[right + 1] - prefix[left + 1] - dp[left + 1][right];
      const takeRight = prefix[right] - prefix[left] - dp[left][right - 1];
      dp[left][right] = Math.max(takeLeft, takeRight);
    }
  }
  return dp[0][n - 1];
}

