function stoneGameVII(stones) {
  // Plain minimax over every sequence of moves: Alice maximises, Bob minimises.
  const play = (lo, hi, aliceTurn) => {
    if (lo > hi) return 0;
    let total = 0;
    for (let k = lo; k <= hi; k++) total += stones[k];
    const gainFront = total - stones[lo];
    const gainBack = total - stones[hi];
    if (aliceTurn) return Math.max(gainFront + play(lo + 1, hi, false), gainBack + play(lo, hi - 1, false));
    return Math.min(play(lo + 1, hi, true) - gainFront, play(lo, hi - 1, true) - gainBack);
  };
  return play(0, stones.length - 1, true);
}

