function generate(rand, size) {
  if (size === 'large') {
    const n = 900 + Math.floor(rand() * 101);
    return [Array.from({ length: n }, () => 1 + Math.floor(rand() * 1000))];
  }
  const n = 2 + Math.floor(rand() * 9);
  const pick = rand();
  const top = pick < 0.3 ? 3 : pick < 0.6 ? 20 : 1000;
  return [Array.from({ length: n }, () => 1 + Math.floor(rand() * top))];
}
